import { useEffect, useRef } from 'preact/compat';
import { useState } from 'preact/hooks';
import { useText } from '@adobe-commerce/elsie/i18n';
import {
  PayPalButtons as PayPalButtonsPaymentMethod,
  PayPalButtonsRenderConfig,
} from '@adobe-commerce/payment-services-sdk/payment';
import { events } from '@adobe-commerce/event-bus';
import * as signals from '@/lib/signals';
import LocalizedError, { fromPaymentsSDKError } from '@/lib/localizedError';
import { randomAlphanumericSuffix } from '@/lib/utils';

export interface PayPalButtonsProps {
  /**
   * Called when a PayPal button is clicked. This callback receives a 'showPaymentSheet'
   * function that must be called to begin the PayPal session and show the payment sheet.
   * If not called, the PayPal session will not start.
   *
   * If no 'onButtonClick' callback is provided, then the PayPal session will begin and the
   * payment sheet will show on button click, always.
   *
   * IMPORTANT: The 'showPaymentSheet' function MUST be called synchronously. If called
   *        ... asynchronously, calling 'showPaymentSheet' will throw exception:
   *        "showPaymentSheet() must be called synchronously inside the onButtonClick callback."
   */
  onButtonClick?: (showPaymentSheet: () => void) => void;
  /**
   * Called when payment flow is successful.
   */
  onSuccess?: (result: { cartId: string }) => void;
  /**
   * Called when the payment flow was aborted due to an error.
   *
   * The function receives an object with two properties, { name: string, message: string }, containing
   * the localized error name and message. Both properties are user-facing and can be translated using
   * the "PaymentServices.PayPalButtons.errors" language definitions.
   */
  onError?: (localizedError: LocalizedError) => void;
  /**
   * Whether the buttons are hidden. Set this to true to hide the PayPal buttons (default: false).
   */
  hidden?: boolean;
  /**
   * Whether the buttons are disabled. Set this to true to disable the PayPal buttons (default: false).
   */
  disabled?: boolean;
}

const CONTAINER_CSS_CLASS = 'payment-services_paypal-buttons-container';

export const PayPalButtons = ({
  onButtonClick,
  onSuccess,
  onError,
  hidden,
  disabled,
}: PayPalButtonsProps) => {
  const sdk = signals.paymentsSDK.value?.checkout;
  const [payPalButtons, setPayPalButtons] =
    useState<PayPalButtonsPaymentMethod | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const initialDisabled = useRef<boolean>(!!disabled);

  const {
    methodNotAvailableMessage,
    methodNotLoadedMessage,
    methodLoadingMessage,
  } = useText({
    methodNotAvailableMessage: 'PaymentServices.messages.methodNotAvailable',
    methodNotLoadedMessage: 'PaymentServices.messages.methodNotLoaded',
    methodLoadingMessage: 'PaymentServices.messages.methodLoading',
  });

  useEffect(() => {
    if (!sdk?.Payment.PayPalButtons.isAvailable()) return;
    if (!containerRef.current) return;

    const containerId = `paypal-buttons-${randomAlphanumericSuffix()}`;
    containerRef.current.id = containerId;

    const renderConfig: PayPalButtonsRenderConfig = {
      container: `#${containerId}`,
      getCartId: async () => {
        const id = events.lastPayload('cart/data')?.id;
        if (!id) {
          throw new Error('PayPal: cart/data payload is not available yet.');
        }
        return id;
      },
      onButtonClick,
      onSuccess,
      onError: (error) => {
        if (onError === undefined) {
          console.error(error);
        } else {
          onError(fromPaymentsSDKError('PayPalButtons', error));
        }
      },
      disabled: initialDisabled.current,
    };

    let newPayPalButtonsInstance: PayPalButtonsPaymentMethod | null = null;
    sdk.Payment.PayPalButtons.render(renderConfig)
      .then((instance) => {
        newPayPalButtonsInstance = instance;
        setPayPalButtons(newPayPalButtonsInstance);
      })
      .catch((error) => {
        console.error('PayPal Buttons render failed:', error);
      });

    return () => {
      if (newPayPalButtonsInstance) {
        newPayPalButtonsInstance.teardown();
      }
    };
  }, [sdk, onButtonClick, onSuccess, onError]);

  useEffect(() => {
    if (payPalButtons) {
      payPalButtons.setDisabled(!!disabled);
    }
  }, [payPalButtons, disabled]);

  const styles = {
    display: hidden ? 'none' : 'block',
  };

  if (sdk && !sdk.Payment.PayPalButtons.isAvailable()) {
    return (
      <div ref={containerRef} class={CONTAINER_CSS_CLASS} style={styles}>
        <div class="paypal-buttons-error">{methodNotAvailableMessage}</div>
      </div>
    );
  }

  if (signals.status.value === 'error') {
    return (
      <div ref={containerRef} class={CONTAINER_CSS_CLASS} style={styles}>
        <div class="paypal-buttons-error">{methodNotLoadedMessage}</div>
      </div>
    );
  }

  if (signals.status.value === 'initializing') {
    return (
      <div ref={containerRef} class={CONTAINER_CSS_CLASS} style={styles}>
        <div class="paypal-buttons-loading">{methodLoadingMessage}</div>
      </div>
    );
  }

  return (
    <div ref={containerRef} class={CONTAINER_CSS_CLASS} style={styles}>
      {/* PayPal buttons will be rendered here by the SDK */}
    </div>
  );
};
